// Algorithms map: "Watch it work" walkthroughs for the remaining algorithms (KNN, SVM, CNN, RNN/LSTM,
// hierarchical clustering, DBSCAN, t-SNE/UMAP, isolation forest, autoencoder).
(function () {
  "use strict";
  const A = window.WB_ALGOS;
  if (!A || !A.story) return;
  const pct = (v) => Math.round(v * 100) + "%", f2 = (v) => v.toFixed(2);
  const clamp = (v) => Math.max(0.03, Math.min(0.97, v));
  const cloud = (r, n, cx, cy, sd, extra = {}) => Array.from({ length: n }, () => Object.assign({ x: clamp(cx + A.sgauss(r) * sd), y: clamp(cy + A.sgauss(r) * sd) }, extra));
  // Small pixel grid drawn in canvas pixels: vals is a flat array, colour(v, i) gives each cell's fill
  const pix = (S, u, v, cols, vals, cell, colour, o = {}) => vals.forEach((val, i) => { const x = S.x(u) + (i % cols) * cell, y = S.y(v) + Math.floor(i / cols) * cell; S.ctx.fillStyle = colour(val, i); S.ctx.fillRect(x + 1, y + 1, cell - 2, cell - 2); if (o.text) { S.ctx.font = `600 ${Math.max(9, cell * 0.36)}px system-ui`; S.ctx.fillStyle = o.textCol || S.pal.fg; S.ctx.textAlign = "center"; S.ctx.textBaseline = "middle"; S.ctx.fillText(o.text(val, i), x + cell / 2, y + cell / 2); } });
  const frameBox = (S, u, v, cols, rows, cell, col, lw = 3) => { S.ctx.lineWidth = lw; S.ctx.strokeStyle = col; S.ctx.strokeRect(S.x(u) + 0.5, S.y(v) + 0.5, cols * cell - 1, rows * cell - 1); };

  /* ---------- K-nearest neighbours ---------- */
  A.story("knn", {
    how: "Watch KNN classify a new point: no training, just a stored set of labelled examples. Measure the distance to every one, take the k closest, and let them vote. Then see how k changes the decision map, and why features must be on the same scale.",
    scenes(S) {
      const p = S.pal, r = A.seeded(61), pts = cloud(r, 26, 0.32, 0.38, 0.13, { c: 0 }).concat(cloud(r, 26, 0.66, 0.62, 0.13, { c: 1 })), Q = { x: 0.5, y: 0.47 }, K = 5;
      const d = (a, b) => Math.hypot(a.x - b.x, a.y - b.y), sorted = pts.map((q, i) => ({ i, d: d(q, Q) })).sort((a, b) => a.d - b.d), nn = sorted.slice(0, K);
      const votesB = nn.filter((n) => pts[n.i].c).length, win = votesB * 2 > K ? 1 : 0;
      const G = 34, mapFor = (k) => Array.from({ length: G * G }, (_, j) => { const g = { x: ((j % G) + 0.5) / G, y: 1 - (Math.floor(j / G) + 0.5) / G }; return pts.map((q) => ({ c: q.c, d: d(q, g) })).sort((a, b) => a.d - b.d).slice(0, k).filter((q) => q.c).length / k; });
      const map1 = mapFor(1), map15 = mapFor(15);
      const g = S.area(0.05, 0.08, 0.58, 0.94), col = (c) => (c ? p.b : p.a);
      const shade = (m, a = 1) => S.alpha(a, () => { const cw = (g.X(1) - g.X(0)) / G, ch = (g.Y(0) - g.Y(1)) / G; m.forEach((v, j) => { S.ctx.fillStyle = S.tint(v >= 0.5 ? p.b : p.a, 0.08 + 0.3 * Math.abs(2 * v - 1)); S.ctx.fillRect(g.X(0) + (j % G) * cw, g.Y(1) + Math.floor(j / G) * ch, cw + 0.5, ch + 0.5); }); });
      const base = (o = {}) => { g.frame("age (scaled) →", "↑ income (scaled)"); pts.forEach((q, i) => g.dot(q.x, q.y, o.hl && o.hl.includes(i) ? 7 : 5, col(q.c), o.hl && o.hl.includes(i) ? S.hl : p.bg)); };
      const query = (c) => { g.dot(Q.x, Q.y, 9, c == null ? p.fg : col(c), S.hl); if (c == null) g.text("?", Q.x, Q.y, { size: 11, color: p.bg }); };
      const side = (lines) => lines.forEach(([t, o], i) => S.text(t, 0.63, 0.2 + i * 0.08, Object.assign({ align: "left", size: 13, max: 0.35 }, o)));
      return [
        { t: "Stored examples", dur: 1600, cap: "Each dot is an existing customer, placed by age and income: teal = did not join the loyalty scheme (A), red = joined (B). KNN's \"training\" is just remembering them, which is why it's called a lazy learner.", draw(S, k) { g.frame("age (scaled) →", "↑ income (scaled)"); pts.slice(0, Math.ceil(k * pts.length)).forEach((q) => g.dot(q.x, q.y, 5, col(q.c), p.bg)); } },
        { t: "A new point arrives", dur: 1400, cap: "A new customer walks in. Will they join? They sit right between the two groups.", draw(S, k) { base(); S.alpha(S.ease(k), () => query(null)); } },
        { t: "Measure every distance", dur: 2600, cap: "Measure the straight-line (Euclidean) distance from the new point to every stored example. That's why prediction is slow on big datasets: it compares with everything.", draw(S, k) { base(); const n = Math.ceil(S.ease(k) * pts.length); pts.slice(0, n).forEach((q) => g.line(Q.x, Q.y, q.x, q.y, S.tint(p.muted, 0.35), 1)); query(null); side([["distance = √(Δx² + Δy²)", { mono: true, size: 12 }], [`${n} distances measured`, { color: p.muted }]]); } },
        { t: `Keep the ${K} nearest`, dur: 2400, cap: `Sort by distance and keep the k = ${K} closest. The circle reaches just far enough to include them.`, draw(S, k) { base({ hl: nn.map((n) => n.i) }); S.ring(g.u(Q.x), g.v(Q.y), (g.X(nn[K - 1].d) - g.X(0)) * S.ease(k) + 4, S.hl, 2); nn.forEach((n) => g.line(Q.x, Q.y, pts[n.i].x, pts[n.i].y, S.hl, 2)); query(null); side(nn.map((n, j) => [`${j + 1}. class ${pts[n.i].c ? "B" : "A"}   d = ${f2(n.d)}`, { mono: true, size: 12, color: col(pts[n.i].c) }])); } },
        { t: "Majority vote", dur: 2200, cap: `The neighbours vote: ${K - votesB} for A, ${votesB} for B. The majority wins, so the prediction is: ${win ? "will join (B)" : "won't join (A)"}. For regression, KNN would average the neighbours' values instead.`, draw(S, k) { base({ hl: nn.map((n) => n.i) }); nn.forEach((n) => g.line(Q.x, Q.y, pts[n.i].x, pts[n.i].y, S.hl, 2)); query(k > 0.5 ? win : null); side([[`A: ${"●".repeat(K - votesB)}`, { color: p.a, size: 16 }], [`B: ${"●".repeat(votesB)}`, { color: p.b, size: 16 }], [k > 0.5 ? `→ class ${win ? "B" : "A"}` : "", { size: 16 }]]); } },
        { t: "How k changes things", dur: 3600, cap: "Do this for every spot on the map. With k = 1 (left half of the animation) the map follows every single point, including noise: it overfits. With k = 15 it's smooth but can blur real edges. Choose k with cross-validation.", draw(S, k) { const one = k < 0.5; shade(one ? map1 : map15); base(); side([[one ? "k = 1" : "k = 15", { size: 18 }], [one ? "jagged: follows every point" : "smooth: majority of 15", { color: p.muted }]]); } },
        { t: "Scale your features", dur: 2600, cap: "Warning: distance adds up raw differences. If one feature is income in dollars (differences of thousands) and another is age in years (differences of tens), income completely drowns out age. Always standardise features before KNN.", draw(S, k) { side([["person A: age 30, income $50,000", { mono: true, size: 12 }], ["person B: age 60, income $51,000", { mono: true, size: 12 }], ["distance ≈ √(30² + 1000²) ≈ 1000", { mono: true, size: 12, color: p.bad }], ["→ age barely counts!", { color: p.bad }], ["after scaling, both count fairly", { color: p.good }]]); shade(map15, 0.5); base(); } },
      ];
    },
  });

  /* ---------- SVM ---------- */
  A.story("svm", {
    how: "Watch a support vector machine pick its boundary: many lines separate the classes, but SVM wants the widest empty street between them. Only the points on the edge of the street matter. Then see soft margins and the kernel trick for curved data.",
    scenes(S) {
      const p = S.pal, r = A.seeded(71), pts = cloud(r, 20, 0.3, 0.35, 0.08, { c: -1 }).concat(cloud(r, 20, 0.68, 0.66, 0.08, { c: 1 }));
      // Exact search for the widest street (separable data): try every direction, measure the gap
      const street = (th) => { const nx = Math.cos(th), ny = Math.sin(th), pr = pts.map((q) => q.x * nx + q.y * ny), lo = Math.max(...pr.filter((v, i) => pts[i].c < 0)), hi = Math.min(...pr.filter((v, i) => pts[i].c > 0)); return { th, nx, ny, gap: hi - lo, mid: (hi + lo) / 2, lo, hi }; };
      let best = street(0); for (let th = 0; th < Math.PI * 2; th += 0.002) { const s = street(th); if (s.gap > best.gap) best = s; }
      const sv = pts.map((q, i) => i).filter((i) => Math.abs(pts[i].x * best.nx + pts[i].y * best.ny - (pts[i].c < 0 ? best.lo : best.hi)) < 1e-9);
      const g = S.area(0.05, 0.08, 0.6, 0.94);
      const lineAt = (s, off, col, lw, dash) => { const c = s.mid + off, dx = -s.ny, dy = s.nx; g.line(c * s.nx - dx, c * s.ny - dy, c * s.nx + dx, c * s.ny + dy, col, lw, dash); };
      const band = (s, col) => { const dx = -s.ny, dy = s.nx, h = s.gap / 2; S.ctx.beginPath(); [[-h, -1], [-h, 1], [h, 1], [h, -1]].forEach(([o, t], j) => { const c = s.mid + o, X = g.X(c * s.nx + dx * t), Y = g.Y(c * s.ny + dy * t); j ? S.ctx.lineTo(X, Y) : S.ctx.moveTo(X, Y); }); S.ctx.closePath(); S.ctx.fillStyle = col; S.ctx.fill(); };
      const base = (o = {}) => { g.frame(); pts.forEach((q, i) => g.dot(q.x, q.y, 5, q.c > 0 ? p.b : p.a, p.bg)); if (o.sv) sv.forEach((i) => S.ring(g.u(pts[i].x), g.v(pts[i].y), 10, S.hl, 3)); };
      const cands = [street(best.th + 0.35), street(best.th - 0.3), best].map((s) => Object.assign({}, s, { gap: Math.max(0.004, s.gap) }));
      const side = (lines) => lines.forEach(([t, o], i) => S.text(t, 0.65, 0.2 + i * 0.08, Object.assign({ align: "left", size: 13, max: 0.33 }, o)));
      const in1 = [-0.9, -0.75, -0.6, -0.45, 0.45, 0.6, 0.75, 0.9], mid1 = [-0.3, -0.15, 0, 0.15, 0.3];
      return [
        { t: "Two classes", dur: 1500, cap: "Each dot is a tissue sample, placed by two of its measurements: teal = healthy, red = diseased. We want a boundary that separates them and also works for new samples we haven't seen yet.", draw(S, k) { g.frame(); pts.slice(0, Math.ceil(k * pts.length)).forEach((q) => g.dot(q.x, q.y, 5, q.c > 0 ? p.b : p.a, p.bg)); } },
        { t: "Many lines work", dur: 2200, cap: "Lots of different lines separate these classes perfectly. Which one is best? A line that squeezes past some points will misclassify new points that land slightly differently.", draw(S, k) { base(); cands.slice(0, 2).forEach((s, j) => S.alpha(S.part(k, j * 0.4, j * 0.4 + 0.4), () => lineAt(s, 0, p.muted, 2.5))); S.alpha(S.part(k, 0.7, 1), () => lineAt(best, 0, p.muted, 2.5)); } },
        { t: "Measure each street", dur: 3000, cap: "For each line, widen it into a street until it touches the nearest points. The width of that empty street is the margin. A wider margin means more room for error with new data.", draw(S, k) { base(); const j = Math.min(2, Math.floor(k * 3)), s = cands[j]; band(s, S.tint(S.hl, 0.18)); lineAt(s, 0, p.fg, 2.5); lineAt(s, -s.gap / 2, p.muted, 1.5, [5, 4]); lineAt(s, s.gap / 2, p.muted, 1.5, [5, 4]); side([[`candidate ${j + 1}`, { color: p.muted }], [`margin width: ${f2(s.gap)}`, { size: 16 }]]); } },
        { t: "The widest street", dur: 2400, cap: `SVM picks the line with the widest possible street (margin ${f2(best.gap)}). The circled points sit exactly on the edges: they are the support vectors, and they alone hold the street in place.`, draw(S, k) { band(best, S.tint(S.hl, 0.2)); base({ sv: k > 0.4 }); lineAt(best, 0, p.fg, 3); lineAt(best, -best.gap / 2, p.muted, 1.5, [5, 4]); lineAt(best, best.gap / 2, p.muted, 1.5, [5, 4]); side([[`margin: ${f2(best.gap)}`, { size: 16 }], [`support vectors: ${sv.length}`, { color: S.hl }]]); } },
        { t: "Only edge points matter", dur: 2800, cap: "Move any point that isn't a support vector (as long as it stays out of the street) and the boundary doesn't budge. That's why SVMs are memory-efficient: the model only needs the support vectors.", draw(S, k) { band(best, S.tint(S.hl, 0.2)); const far = pts.reduce((b, q, i) => (q.c > 0 && q.x + q.y > pts[b].x + pts[b].y ? i : b), 0), save = { x: pts[far].x, y: pts[far].y }; pts[far].x = clamp(save.x + 0.12 * Math.sin(k * Math.PI)); pts[far].y = clamp(save.y + 0.06 * Math.sin(k * Math.PI)); base({ sv: true }); S.ring(g.u(pts[far].x), g.v(pts[far].y), 12, p.good, 2); pts[far].x = save.x; pts[far].y = save.y; lineAt(best, 0, p.fg, 3); } },
        { t: "Soft margin (C)", dur: 2600, cap: "Real data overlaps, so a perfect street may not exist. A soft margin lets a few points sit inside the street or on the wrong side, at a cost set by C. Large C = strict, narrow street (can overfit); small C = wider, more tolerant street.", draw(S, k) { band(best, S.tint(S.hl, 0.2)); base(); const o = { x: best.mid * best.nx + best.nx * 0.01, y: best.mid * best.ny + best.ny * 0.01 }; S.alpha(S.ease(k), () => { g.dot(o.x - best.ny * 0.1, o.y + best.nx * 0.1, 6, p.a, p.bad); g.text("tolerated violation", o.x - best.ny * 0.1, o.y + best.nx * 0.1 + 0.06, { size: 11, color: p.bad }); }); lineAt(best, 0, p.fg, 3); side([["minimise:", { color: p.muted }], ["½‖w‖² + C · Σ violations", { mono: true }]]); } },
        { t: "The kernel trick", dur: 3800, cap: "What if no straight line can work? Here the red points sit between the teal ones on a single line. Add a new feature, x², and lift each point up: now a flat line separates them. Kernels (like RBF) do this kind of lift implicitly, giving curved boundaries back in the original space.", draw(S, k) { const h = S.area(0.08, 0.12, 0.92, 0.86), e = S.ease(S.part(k, 0.25, 0.8)); h.line(0, 0.08, 1, 0.08, p.line, 1.5); h.text("x", 1.01, 0.08, { size: 12, color: p.muted }); const X = (v) => 0.5 + v * 0.45; in1.forEach((v) => h.dot(X(v), 0.08 + e * v * v * 0.95, 6, p.a, p.bg)); mid1.forEach((v) => h.dot(X(v), 0.08 + e * v * v * 0.95, 6, p.b, p.bg)); S.alpha(e, () => h.path(Array.from({ length: 41 }, (_, i) => { const v = -1 + i / 20; return [X(v), 0.08 + v * v * 0.95]; }), S.tint(p.muted, 0.5), 1.5)); S.alpha(S.part(k, 0.8, 1), () => { h.line(0, 0.08 + 0.16 * 0.95, 1, 0.08 + 0.16 * 0.95, S.hl, 3); h.text("now a straight line separates them", 0.5, 0.35, { size: 13, color: S.hl }); h.text("new feature: x²", 0.06, 0.95, { size: 12, color: p.muted, align: "left" }); }); } },
      ];
    },
  });

  /* ---------- CNN ---------- */
  A.story("cnn", {
    how: "Watch a convolutional network look at an image: a 3×3 filter slides across the pixels, multiplying and adding at each position to build a feature map that lights up on vertical edges. Then ReLU, pooling, many filters, deeper layers, and a final classification.",
    scenes(S) {
      const p = S.pal, N = 8;
      const img = Array.from({ length: N * N }, (_, i) => { const r = Math.floor(i / N), c = i % N; return (c >= 2 && c <= 5 && r >= 1 && r <= 6) && !(c >= 3 && c <= 4 && r >= 3 && r <= 4) ? 1 : 0; });
      const KER = [-1, 0, 1, -1, 0, 1, -1, 0, 1], M = N - 2;
      const conv = Array.from({ length: M * M }, (_, j) => { const r = Math.floor(j / M), c = j % M; let s = 0; for (let a = 0; a < 3; a++) for (let b = 0; b < 3; b++) s += img[(r + a) * N + c + b] * KER[a * 3 + b]; return s; });
      const relu = conv.map((v) => Math.max(0, v)), P = M / 2, pool = Array.from({ length: P * P }, (_, j) => { const r = Math.floor(j / P) * 2, c = (j % P) * 2; return Math.max(relu[r * M + c], relu[r * M + c + 1], relu[(r + 1) * M + c], relu[(r + 1) * M + c + 1]); });
      const mx = 3, cell = () => Math.min(S.x(0.042), S.y(0.09));
      const imgCol = (v) => (v ? p.fg : S.tint(p.line, 0.6)), mapCol = (v) => S.tint(v >= 0 ? p.a : p.b, 0.12 + 0.8 * Math.min(1, Math.abs(v) / mx));
      const drawImg = (hl) => { const c = cell(); S.text("input image (8×8 pixels)", 0.04, 0.1, { size: 11, color: p.muted, align: "left" }); pix(S, 0.04, 0.14, N, img, c, imgCol); if (hl != null) { const r = Math.floor(hl / M), cc = hl % M; S.ctx.lineWidth = 3; S.ctx.strokeStyle = S.hl; S.ctx.strokeRect(S.x(0.04) + cc * c, S.y(0.14) + r * c, 3 * c, 3 * c); } };
      const drawKer = (u = 0.44, v = 0.18) => { const c = cell() * 0.9; S.text("filter (3×3)", u, v - 0.05, { size: 11, color: p.muted, align: "left" }); pix(S, u, v, 3, KER, c, (w) => S.tint(w > 0 ? p.a : w < 0 ? p.b : p.line, w ? 0.5 : 0.4), { text: (w) => (w > 0 ? "+1" : w < 0 ? "−1" : "0") }); };
      const drawMap = (vals, n, upto, u = 0.62, v = 0.14, label = "feature map (6×6)") => { const c = cell(); S.text(label, u, v - 0.04, { size: 11, color: p.muted, align: "left" }); pix(S, u, v, n, vals.map((x, i) => (i < upto ? x : null)), c, (x) => (x == null ? S.tint(p.line, 0.25) : mapCol(x)), { text: (x) => (x == null ? "" : String(x)) }); };
      return [
        { t: "An image is numbers", dur: 1800, cap: "To a computer, an image is a grid of numbers: here 8×8 pixels, 1 = ink, 0 = blank. A real photo is millions of numbers (×3 for red, green and blue).", draw(S, k) { drawImg(); S.alpha(S.ease(k), () => pix(S, 0.5, 0.14, N, img, cell() * 0.8, () => "rgba(0,0,0,0)", { text: (v) => String(v), textCol: p.muted })); } },
        { t: "A filter", dur: 1800, cap: "A filter (kernel) is a tiny grid of weights. This one has −1s on the left and +1s on the right: it responds to a vertical edge where dark changes to light, or light to dark. In a real CNN these weights are learned.", draw(S, k) { drawImg(); S.alpha(S.ease(k), () => drawKer()); } },
        { t: "Slide and multiply", dur: 9000, cap: (k) => { const j = Math.min(M * M - 1, Math.floor(k * M * M)); return `Position ${j + 1} of ${M * M}: multiply each pixel under the yellow window by the matching filter weight and add them up → ${conv[j]}. Big positive = edge one way, big negative = edge the other way, 0 = no edge.`; }, draw(S, k) { const j = Math.min(M * M - 1, Math.floor(k * M * M)); drawImg(j); drawKer(0.44, 0.62); drawMap(conv, M, j + 1); } },
        { t: "ReLU", dur: 2000, cap: "Apply ReLU: keep positive values, turn negatives into 0. This adds the non-linearity that lets stacked layers learn complex patterns.", draw(S, k) { drawImg(); drawMap(k > 0.4 ? relu : conv, M, M * M, 0.62, 0.14, k > 0.4 ? "after ReLU" : "feature map"); } },
        { t: "Pooling", dur: 2400, cap: "Max pooling keeps the strongest value in each 2×2 block: the 6×6 map shrinks to 3×3. Less to compute, and the network becomes tolerant of small shifts: an edge one pixel to the left still counts.", draw(S, k) { drawMap(relu, M, M * M, 0.06, 0.14, "after ReLU (6×6)"); S.alpha(S.ease(k), () => { S.arrow(0.38, 0.4, 0.5, 0.4, p.fg, 2); drawMap(pool, P, P * P, 0.56, 0.24, "max-pooled (3×3)"); }); } },
        { t: "Many filters", dur: 2400, cap: "A real layer has dozens or hundreds of filters, each producing its own feature map: vertical edges, horizontal edges, diagonals, colour blobs. Nobody designs them; training finds the useful ones.", draw(S, k) { drawImg(); ["vertical edge", "horizontal edge", "diagonal", "corner"].forEach((l, i) => S.alpha(S.part(k, i * 0.2, i * 0.2 + 0.3), () => S.box(0.55 + (i % 2) * 0.22, 0.28 + Math.floor(i / 2) * 0.36, 0.18, 0.26, l, { sub: "feature map", stroke: i ? p.line : S.hl }))); } },
        { t: "Deeper layers, then classify", dur: 3000, cap: "Layers stack: early ones find edges, middle ones combine edges into shapes (corners, curves), deep ones respond to whole objects (an eye, a wheel). A final layer turns the features into class probabilities.", draw(S, k) { [["layer 1", "edges"], ["layer 2", "shapes"], ["layer 3", "parts"], ["output", "classes"]].forEach(([a, b], i) => S.alpha(S.part(k, i * 0.18, i * 0.18 + 0.25), () => { S.box(0.1 + i * 0.2, 0.4, 0.15, 0.22, a, { sub: b }); if (i < 3) S.arrow(0.18 + i * 0.2, 0.4, 0.22 + i * 0.2, 0.4, p.muted, 1.5); })); [["letter O", 0.86], ["letter D", 0.09], ["letter C", 0.05]].forEach(([l, v], i) => S.alpha(S.part(k, 0.75, 1), () => { S.text(l, 0.62, 0.72 + i * 0.08, { size: 12, align: "right" }); S.rect(0.64, 0.7 + i * 0.08, 0.3 * v, 0.04, i ? S.tint(p.accent, 0.5) : S.hl); S.text(pct(v), 0.66 + 0.3 * v, 0.72 + i * 0.08, { size: 11, align: "left" }); })); } },
      ];
    },
  });

  /* ---------- RNN / LSTM ---------- */
  A.story("rnn", {
    how: "Watch a recurrent network read a review one word at a time, carrying a memory forward. A plain RNN's memory fades, so the early word \"terrible\" is forgotten and it guesses wrong. An LSTM's gates protect important information, so it remembers.",
    note: "Simplified: the memory is a single number with hand-set rules, to show fading vs gated memory.",
    scenes(S) {
      const p = S.pal, words = ["terrible", "plot", ",", "boring", "actors", ", but", "nice", "music"], sent = [-1, 0, 0, -0.8, 0, 0, 0.7, 0];
      const rnn = [], lstm = []; { let h = 0, c = 0; sent.forEach((s) => { h = 0.5 * h + s; rnn.push(h); c = (s ? 0.95 : 0.97) * c + s; lstm.push(c); }); }
      const U = (i) => 0.08 + i * 0.115;
      const row = (n, hl) => words.forEach((w, i) => S.alpha(i < n ? 1 : 0.25, () => S.box(U(i), 0.2, 0.1, 0.08, w, { stroke: i === hl ? S.hl : p.line, lw: i === hl ? 3 : 1.5, color: sent[i] < 0 ? p.b : sent[i] > 0 ? p.a : p.fg })));
      const mem = (vals, n, v0, label, col) => { S.text(label, 0.02, v0 - 0.1, { size: 12, color: p.muted, align: "left" }); S.line(0.03, v0, 0.98, v0, p.line, 1); vals.slice(0, n).forEach((h, i) => { const hh = Math.max(-1.8, Math.min(1.8, h)) * 0.08; S.rect(U(i) - 0.03, Math.min(v0, v0 - hh), 0.06, Math.abs(hh), S.tint(h < 0 ? p.b : p.a, 0.75)); if (i) S.arrow(U(i - 1) + 0.035, v0 + 0.09, U(i) - 0.035, v0 + 0.09, col, 1.5, 6); S.text(h.toFixed(2), U(i), v0 + 0.14, { size: 10.5 }); }); };
      const verdict = (h, v) => S.text(`final memory ${h.toFixed(2)} → ${h < 0 ? "NEGATIVE review ✓" : "POSITIVE review ✗"}`, 0.5, v, { size: 14, color: h < 0 ? p.good : p.bad });
      return [
        { t: "Reading a sequence", dur: 2200, cap: "The task: is this review positive or negative? A recurrent network reads it one word at a time, left to right, like we do, using the same weights at every step.", draw(S, k) { row(Math.ceil(S.ease(k) * words.length)); } },
        { t: "Carrying a memory", dur: 2400, cap: "After each word it updates a hidden state (its memory) from two things: the new word, and the memory so far. h_new = tanh(W·word + U·h_old). That memory is passed along to the next step.", draw(S, k) { row(2, 1); S.box(0.3, 0.55, 0.2, 0.14, "memory h₁", { stroke: p.accent }); S.box(0.62, 0.55, 0.2, 0.14, "memory h₂", { stroke: S.hl }); S.arrow(0.4, 0.55, 0.52, 0.55, p.fg, 2); S.arrow(U(1), 0.25, 0.6, 0.47, p.fg, 1.5); S.text("h₂ = tanh(W·\"plot\" + U·h₁)", 0.5, 0.78, { mono: true, size: 13 }); } },
        { t: "A plain RNN reads it", dur: 5000, cap: (k) => { const n = Math.max(1, Math.ceil(S.ease(k) * words.length)); return `Word ${n} ("${words[n - 1]}"): memory ${rnn[n - 1].toFixed(2)}. Each step the old memory is squeezed again, so "terrible" fades fast, and the late word "nice" dominates.`; }, draw(S, k) { const n = Math.max(1, Math.ceil(S.ease(k) * words.length)); row(n, n - 1); mem(rnn, n, 0.62, "plain RNN memory", p.muted); } },
        { t: "The wrong answer", dur: 2200, cap: "The plain RNN ends positive because the strong negative words at the start have been forgotten. Its memory keeps roughly half of the past at every step, so after 7 steps less than 1% of \"terrible\" is left.", draw(S, k) { row(8); mem(rnn, 8, 0.62, "plain RNN memory", p.muted); S.alpha(S.ease(k), () => verdict(rnn[7], 0.92)); } },
        { t: "Why: vanishing gradients", dur: 2600, cap: "Training has the same problem in reverse: the learning signal for early words is multiplied by a small factor at every step back (backpropagation through time), so it vanishes. Early words barely get learned.", draw(S, k) { const g = S.area(0.1, 0.18, 0.9, 0.85); g.frame("steps back in time →", "signal left"); g.path(Array.from({ length: Math.max(2, Math.ceil(S.ease(k) * 20)) }, (_, i) => [i / 19, Math.pow(0.5, i)]), p.bad, 3); g.text("× 0.5 per step", 0.6, 0.5, { size: 13, color: p.bad }); } },
        { t: "The LSTM cell", dur: 3200, cap: "An LSTM adds a cell state: a conveyor belt running through time that changes only through gates. The forget gate decides what to erase, the input gate what to add, the output gate what to reveal. Strong signals can ride the belt almost unchanged.", draw(S, k) { S.line(0.05, 0.3, 0.95, 0.3, S.hl, 5); S.text("cell state (the conveyor belt)", 0.5, 0.22, { size: 12, color: S.hl }); [["forget gate", "× keep?"], ["input gate", "+ add new"], ["output gate", "→ reveal"]].forEach(([a, b], i) => S.alpha(S.part(k, i * 0.25, i * 0.25 + 0.3), () => { S.box(0.25 + i * 0.25, 0.55, 0.18, 0.14, a, { sub: b, stroke: p.accent }); S.arrow(0.25 + i * 0.25, 0.47, 0.25 + i * 0.25, 0.33, p.accent, 1.5); })); S.alpha(S.part(k, 0.8, 1), () => S.text("gates are small networks outputting 0…1", 0.5, 0.82, { size: 12, color: p.muted })); } },
        { t: "The LSTM reads it", dur: 5000, cap: (k) => { const n = Math.max(1, Math.ceil(S.ease(k) * words.length)); return `Word ${n}: cell state ${lstm[n - 1].toFixed(2)}. The forget gate stays near 1, so "terrible" and "boring" are kept; "nice" only partly offsets them.`; }, draw(S, k) { const n = Math.max(1, Math.ceil(S.ease(k) * words.length)); row(n, n - 1); mem(lstm, n, 0.62, "LSTM cell state", S.hl); } },
        { t: "The right answer", dur: 2400, cap: "The LSTM ends negative: correct. GRUs work similarly with fewer gates. Today transformers usually replace both, because attention can look at every word directly and in parallel, but LSTMs are still used for small time-series and on-device tasks.", draw(S, k) { row(8); mem(rnn, 8, 0.45, "plain RNN", p.muted); mem(lstm, 8, 0.78, "LSTM", S.hl); S.alpha(S.ease(k), () => { verdict(rnn[7], 0.96); }); } },
      ];
    },
  });

  /* ---------- Hierarchical clustering ---------- */
  A.story("hier", {
    how: "Watch agglomerative clustering: every point starts as its own group, the two closest groups merge again and again, the merges build a family tree (a dendrogram), and cutting the tree at a chosen height gives the clusters.",
    scenes(S) {
      const p = S.pal, r = A.seeded(83), raw = cloud(r, 4, 0.25, 0.3, 0.06).concat(cloud(r, 4, 0.72, 0.32, 0.07), cloud(r, 4, 0.48, 0.75, 0.06));
      const pts = raw.map((q, i) => Object.assign(q, { name: "ABCDEFGHIJKL"[i] }));
      // Average-linkage merges
      let groups = pts.map((q, i) => ({ id: i, members: [i], h: 0 })); const merges = [];
      const dist = (a, b) => { let s = 0; a.members.forEach((i) => b.members.forEach((j) => (s += Math.hypot(pts[i].x - pts[j].x, pts[i].y - pts[j].y)))); return s / (a.members.length * b.members.length); };
      let nid = pts.length; while (groups.length > 1) { let best = null; for (let i = 0; i < groups.length; i++) for (let j = i + 1; j < groups.length; j++) { const d = dist(groups[i], groups[j]); if (!best || d < best.d) best = { i, j, d }; } const a = groups[best.i], b = groups[best.j], m = { id: nid++, members: a.members.concat(b.members), h: best.d, a, b }; merges.push(m); groups = groups.filter((g, k) => k !== best.i && k !== best.j).concat([m]); }
      const root = merges[merges.length - 1], order = root.members, hmax = root.h;
      const xpos = {}; order.forEach((i, k) => (xpos[i] = k)); const nodeX = (n) => (n.a ? (nodeX(n.a) + nodeX(n.b)) / 2 : xpos[n.id]);
      const DU = (x) => 0.64 + (x / (order.length - 1)) * 0.32, DV = (h) => 0.88 - (h / hmax) * 0.7;
      const dendro = (upto, cutH) => { S.text("dendrogram", 0.8, 0.08, { size: 11, color: p.muted }); order.forEach((i, k) => S.text(pts[i].name, DU(k), 0.93, { size: 11 })); merges.slice(0, upto).forEach((m) => { const xa = nodeX(m.a), xb = nodeX(m.b); S.line(DU(xa), DV(m.a.h), DU(xa), DV(m.h), p.fg, 2); S.line(DU(xb), DV(m.b.h), DU(xb), DV(m.h), p.fg, 2); S.line(DU(xa), DV(m.h), DU(xb), DV(m.h), p.fg, 2); }); if (cutH != null) { S.line(0.62, DV(cutH), 0.98, DV(cutH), S.hl, 2.5, [6, 4]); S.text("cut", 0.6, DV(cutH), { size: 11, color: S.hl, align: "right" }); } };
      const g = S.area(0.04, 0.08, 0.56, 0.94);
      const clustersAt = (n) => { let gs = pts.map((q, i) => ({ id: i, members: [i] })); merges.slice(0, n).forEach((m) => { gs = gs.filter((x) => !m.members.includes(x.members[0]) || x.members.length > m.members.length).filter((x) => !(x.members.every((i) => m.members.includes(i)))); gs.push(m); }); return gs; };
      const scatter = (n, colour) => { g.frame(); const gs = clustersAt(n); gs.forEach((gr, gi) => { if (gr.members.length > 1) { const xs = gr.members.map((i) => pts[i]); const cx = xs.reduce((s, q) => s + q.x, 0) / xs.length, cy = xs.reduce((s, q) => s + q.y, 0) / xs.length, rad = Math.max(...xs.map((q) => Math.hypot(q.x - cx, q.y - cy))) + 0.05; S.ctx.beginPath(); S.ctx.ellipse(g.X(cx), g.Y(cy), g.X(rad) - g.X(0), g.Y(0) - g.Y(rad), 0, 0, 7); S.ctx.strokeStyle = colour ? p.groups[gi % 6] : S.tint(p.muted, 0.6); S.ctx.lineWidth = 1.5; S.ctx.stroke(); } gr.members.forEach((i) => { g.dot(pts[i].x, pts[i].y, 6, colour ? p.groups[gi % 6] : p.muted, p.bg); g.text(pts[i].name, pts[i].x + 0.035, pts[i].y + 0.035, { size: 10, color: p.muted }); }); }); };
      const cut3 = (merges[merges.length - 3].h + merges[merges.length - 2].h) / 2;
      return [
        { t: "Every point is a group", dur: 1800, cap: "12 species (A–L), placed so that species with similar DNA sit close together. Start by treating each species as its own tiny group. No need to decide the number of groups yet.", draw(S, k) { g.frame(); pts.slice(0, Math.ceil(k * pts.length)).forEach((q) => { g.dot(q.x, q.y, 6, p.muted, p.bg); g.text(q.name, q.x + 0.035, q.y + 0.035, { size: 10, color: p.muted }); }); } },
        { t: "Merge the closest pair", dur: 2200, cap: `Find the two closest groups and merge them: ${merges[0].a.members.map((i) => pts[i].name).join("")} and ${merges[0].b.members.map((i) => pts[i].name).join("")}. The merge is recorded in the dendrogram at a height equal to their distance.`, draw(S, k) { scatter(k > 0.5 ? 1 : 0); const [i, j] = [merges[0].a.members[0], merges[0].b.members[0]]; g.line(pts[i].x, pts[i].y, pts[j].x, pts[j].y, S.hl, 3); dendro(k > 0.5 ? 1 : 0); } },
        { t: "Keep merging", dur: 8000, cap: (k) => { const n = Math.min(merges.length, 1 + Math.floor(S.ease(k) * merges.length)); return `Merge ${n} of ${merges.length}: groups ${merges[n - 1].a.members.map((i) => pts[i].name).join("")} + ${merges[n - 1].b.members.map((i) => pts[i].name).join("")} at distance ${f2(merges[n - 1].h)}. Distance between groups here = average distance between their members (average linkage).`; }, draw(S, k) { const n = Math.min(merges.length, 1 + Math.floor(S.ease(k) * merges.length)); scatter(n); dendro(n); } },
        { t: "The full family tree", dur: 2000, cap: "Eventually everything is one group. The dendrogram is the family tree: low joins = very similar species; high joins = groups that are only distantly related.", draw(S, k) { scatter(merges.length); dendro(merges.length); } },
        { t: "Cut the tree", dur: 2800, cap: "Now choose the number of clusters by cutting the tree horizontally. A good place is across a long vertical gap, where the next merge would join groups that are far apart. Cutting here gives 3 clusters.", draw(S, k) { scatter(merges.length - 2, k > 0.5); dendro(merges.length, S.lerp(hmax * 1.05, cut3, S.ease(k))); } },
        { t: "Linkage choices", dur: 2800, cap: "How do you measure the distance between two groups? Single linkage: the closest pair (finds long chains). Complete: the farthest pair (compact groups). Average: the mean of all pairs (used here). Ward: the merge that adds the least spread.", draw(S, k) { scatter(merges.length - 2, true); const gs = clustersAt(merges.length - 2).filter((x) => x.members.length > 1); if (gs.length >= 2) { const a = gs[0].members, b = gs[1].members; let near = null, far = null; a.forEach((i) => b.forEach((j) => { const d = Math.hypot(pts[i].x - pts[j].x, pts[i].y - pts[j].y); if (!near || d < near.d) near = { i, j, d }; if (!far || d > far.d) far = { i, j, d }; })); S.alpha(S.part(k, 0, 0.4), () => g.line(pts[near.i].x, pts[near.i].y, pts[near.j].x, pts[near.j].y, p.good, 3)); S.alpha(S.part(k, 0.4, 0.8), () => g.line(pts[far.i].x, pts[far.i].y, pts[far.j].x, pts[far.j].y, p.bad, 3, [6, 4])); } [["single = closest pair", p.good], ["complete = farthest pair", p.bad], ["average = mean of all pairs", p.fg]].forEach(([t, c], i) => S.text(t, 0.64, 0.25 + i * 0.1, { size: 13, color: c, align: "left" })); } },
      ];
    },
  });

  /* ---------- DBSCAN ---------- */
  A.story("dbscan", {
    how: "Watch DBSCAN find clusters by density: draw a circle of radius ε around a point and count its neighbours. Crowded points are core points; clusters grow outwards from them through their neighbours; lonely points are labelled noise. It finds shapes K-means can't.",
    scenes(S) {
      const p = S.pal, r = A.seeded(91), pts = [];
      for (let i = 0; i < 55; i++) { const t = Math.PI * r(); pts.push({ x: clamp(0.33 + 0.22 * Math.cos(t) + A.sgauss(r) * 0.018), y: clamp(0.45 + 0.28 * Math.sin(t) + A.sgauss(r) * 0.018) }); }
      for (let i = 0; i < 55; i++) { const t = Math.PI * r(); pts.push({ x: clamp(0.56 + 0.22 * Math.cos(t) + A.sgauss(r) * 0.018), y: clamp(0.58 - 0.28 * Math.sin(t) + A.sgauss(r) * 0.018) }); }
      for (let i = 0; i < 10; i++) pts.push({ x: 0.05 + 0.9 * r(), y: 0.05 + 0.9 * r() });
      const EPS = 0.075, MIN = 4, nb = (i, e = EPS) => pts.map((q, j) => j).filter((j) => Math.hypot(pts[i].x - pts[j].x, pts[i].y - pts[j].y) <= e);
      function dbscan(e) { const lab = pts.map(() => -2), core = pts.map((q, i) => nb(i, e).length >= MIN), order = []; let c = -1; pts.forEach((q, i) => { if (lab[i] !== -2 || !core[i]) return; c++; const queue = [i]; lab[i] = c; order.push([i, c]); while (queue.length) { const j = queue.shift(); if (!core[j]) continue; nb(j, e).forEach((m) => { if (lab[m] < 0) { lab[m] = c; order.push([m, c]); queue.push(m); } }); } }); return { lab: lab.map((v) => (v === -2 ? -1 : v)), core, order, n: c + 1 }; }
      const D = dbscan(EPS), coreEx = D.core.indexOf(true), border = pts.findIndex((q, i) => !D.core[i] && D.lab[i] >= 0), noise = pts.findIndex((q, i) => D.lab[i] < 0);
      const tries = [0.03, EPS, 0.18].map((e) => ({ e, ...dbscan(e) }));
      // K-means with k = 2, for comparison
      let C = [{ x: 0.3, y: 0.5 }, { x: 0.7, y: 0.5 }], km = []; for (let it = 0; it < 15; it++) { km = pts.map((q) => (Math.hypot(q.x - C[0].x, q.y - C[0].y) < Math.hypot(q.x - C[1].x, q.y - C[1].y) ? 0 : 1)); C = [0, 1].map((j) => { const m = pts.filter((q, i) => km[i] === j); return { x: m.reduce((s, q) => s + q.x, 0) / m.length, y: m.reduce((s, q) => s + q.y, 0) / m.length }; }); }
      const g = S.area(0.04, 0.08, 0.62, 0.94), R = () => g.X(EPS) - g.X(0);
      const draw = (colOf, big) => { g.frame(); pts.forEach((q, i) => { const c = colOf(i); g.dot(q.x, q.y, big && D.core[i] ? 5.5 : 4, c, p.bg); }); };
      const side = (lines) => lines.forEach(([t, o], i) => S.text(t, 0.66, 0.2 + i * 0.08, Object.assign({ align: "left", size: 13, max: 0.32 }, o)));
      const circle = (i, col) => { S.ring(g.u(pts[i].x), g.v(pts[i].y), R(), col, 2); };
      return [
        { t: "Odd-shaped data", dur: 1600, cap: "Each dot is a taxi pickup on a city map: two curved busy streets plus a few one-off pickups. No labels. K-means would struggle: it only finds round blobs.", draw(S, k) { g.frame(); pts.slice(0, Math.ceil(k * pts.length)).forEach((q) => g.dot(q.x, q.y, 4, p.muted, p.bg)); } },
        { t: "A core point", dur: 2400, cap: `Pick a point and draw a circle of radius ε around it. Count the points inside: ${nb(coreEx).length}. That's at least minPts = ${MIN}, so this is a core point: it sits in a crowd.`, draw(S, k) { draw(() => p.muted); S.alpha(S.ease(k), () => { circle(coreEx, S.hl); nb(coreEx).forEach((j) => g.dot(pts[j].x, pts[j].y, 5, S.hl)); }); side([[`ε = ${EPS}  (circle radius)`, { mono: true }], [`minPts = ${MIN}`, { mono: true }], [`neighbours: ${nb(coreEx).length} → core`, { color: p.good }]]); } },
        { t: "Border and noise", dur: 2800, cap: `A border point has too few neighbours itself (${nb(border).length}) but sits inside a core point's circle, so it joins that cluster. A noise point has too few neighbours and no core point nearby (${nb(noise).length} in its circle including itself): it's an outlier.`, draw(S, k) { draw(() => p.muted); S.alpha(S.part(k, 0, 0.5), () => { circle(border, p.accent); g.dot(pts[border].x, pts[border].y, 7, p.accent); g.text("border", pts[border].x, pts[border].y + 0.09, { size: 12, color: p.accent }); }); S.alpha(S.part(k, 0.5, 1), () => { circle(noise, p.bad); g.dot(pts[noise].x, pts[noise].y, 7, p.bad); g.text("noise", pts[noise].x, pts[noise].y + 0.09, { size: 12, color: p.bad }); }); } },
        { t: "Grow the clusters", dur: 8000, cap: (k) => { const n = Math.ceil(S.ease(k) * D.order.length), c = n ? D.order[n - 1][1] : 0; return `Start at a core point and spread: every neighbour of a core point joins its cluster, and any core point reached keeps the spread going. Cluster ${c + 1} is growing: ${n} points assigned. When a cluster can't spread any further, start a new one from an unvisited core point.`; }, draw(S, k) { const n = Math.ceil(S.ease(k) * D.order.length), got = new Map(D.order.slice(0, n)); draw((i) => (got.has(i) ? p.groups[got.get(i) % 6] : p.muted), true); if (n) circle(D.order[n - 1][0], S.hl); } },
        { t: "Result", dur: 2400, cap: `DBSCAN found ${D.n} busy zones (one per street) and labelled ${D.lab.filter((v) => v < 0).length} points as noise (grey), all without being told how many clusters there are. Big dots are core points.`, draw(S, k) { draw((i) => (D.lab[i] < 0 ? p.muted : p.groups[D.lab[i] % 6]), true); side([[`clusters: ${D.n}`, { size: 16 }], [`noise: ${D.lab.filter((v) => v < 0).length}`, { color: p.muted }]]); } },
        { t: "K-means vs DBSCAN", dur: 2400, cap: "For comparison, K-means with k = 2 on the same data: it slices straight across both crescents and forces every stray point into a group. DBSCAN follows the shapes and leaves outliers out.", draw(S, k) { const kmView = k < 0.5; draw((i) => (kmView ? [p.groups[2], p.groups[3]][km[i]] : D.lab[i] < 0 ? p.muted : p.groups[D.lab[i] % 6])); side([[kmView ? "K-means (k = 2)" : "DBSCAN", { size: 16 }], [kmView ? "cuts the shapes, no noise" : "follows the shapes", { color: kmView ? p.bad : p.good }]]); } },
        { t: "Choosing ε", dur: 3000, cap: (k) => { const t = tries[Math.min(2, Math.floor(k * 3))]; return `ε = ${t.e}: ${t.n} clusters, ${t.lab.filter((v) => v < 0).length} noise points. Too small and everything is noise or splinters; too big and the crescents merge. Use a k-distance plot to choose; HDBSCAN handles clusters of different densities automatically.`; }, draw(S, k) { const t = tries[Math.min(2, Math.floor(k * 3))]; draw((i) => (t.lab[i] < 0 ? p.muted : p.groups[t.lab[i] % 6])); side([[`ε = ${t.e}`, { size: 16, mono: true }], [`${t.n} clusters`], [`${t.lab.filter((v) => v < 0).length} noise`, { color: p.muted }]]); } },
      ];
    },
  });

  /* ---------- t-SNE / UMAP ---------- */
  A.story("tsne", {
    how: "Watch a high-dimensional dataset become a 2D map: each point has 10 numbers, too many to plot. Find each point's nearest neighbours in the original space, scatter the points randomly, then repeatedly pull neighbours together and push everything else apart until islands appear.",
    note: "Simplified force layout that follows the same idea as t-SNE and UMAP; the real methods use probability-based versions of these forces.",
    scenes(S) {
      const p = S.pal, r = A.seeded(97), D = 10, centres = [0, 1, 2].map(() => Array.from({ length: D }, () => r() * 2 - 1));
      const pts = []; centres.forEach((c, gi) => { for (let i = 0; i < 22; i++) pts.push({ v: c.map((x) => x + A.sgauss(r) * 0.35), g: gi }); });
      const hd = (a, b) => Math.sqrt(a.v.reduce((s, x, i) => s + (x - b.v[i]) ** 2, 0));
      const K = 6; pts.forEach((q, i) => (q.nn = pts.map((b, j) => ({ j, d: hd(q, b) })).filter((x) => x.j !== i).sort((a, b) => a.d - b.d).slice(0, K).map((x) => x.j)));
      let pos = pts.map(() => [0.15 + 0.7 * r(), 0.15 + 0.7 * r()]); const snaps = [pos.map((x) => x.slice())];
      for (let it = 1; it <= 240; it++) {
        const f = pos.map(() => [0, 0]);
        pts.forEach((q, i) => { q.nn.forEach((j) => { f[i][0] += (pos[j][0] - pos[i][0]) * 0.08; f[i][1] += (pos[j][1] - pos[i][1]) * 0.08; }); pts.forEach((b, j) => { if (i === j) return; const dx = pos[i][0] - pos[j][0], dy = pos[i][1] - pos[j][1], d2 = dx * dx + dy * dy + 0.01; f[i][0] += (dx / d2) * 0.0005; f[i][1] += (dy / d2) * 0.0005; }); });
        pos = pos.map(([x, y], i) => [x + Math.max(-0.03, Math.min(0.03, f[i][0])), y + Math.max(-0.03, Math.min(0.03, f[i][1]))]);
        // Re-fit the map into the frame each iteration rather than squashing points against the edges
        const xs = pos.map((q) => q[0]), ys = pos.map((q) => q[1]), x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys), s = Math.max(x1 - x0, y1 - y0, 1e-9);
        pos = pos.map(([x, y]) => [0.08 + (0.84 * (x - x0)) / s + (0.84 - (0.84 * (x1 - x0)) / s) / 2, 0.08 + (0.84 * (y - y0)) / s + (0.84 - (0.84 * (y1 - y0)) / s) / 2]);
        if (it % 8 === 0) snaps.push(pos.map((x) => x.slice()));
      }
      const g = S.area(0.06, 0.08, 0.64, 0.94), focus = 5;
      const show = (P, colour, o = {}) => { g.frame(); P.forEach(([x, y], i) => g.dot(x, y, i === focus && o.focus ? 8 : 5, colour ? p.groups[[0, 3, 2][pts[i].g]] : p.muted, i === focus && o.focus ? S.hl : p.bg)); };
      const side = (lines) => lines.forEach(([t, o], i) => S.text(t, 0.68, 0.2 + i * 0.08, Object.assign({ align: "left", size: 13, max: 0.3 }, o)));
      return [
        { t: "Too many numbers to plot", dur: 2200, cap: `Each of these ${pts.length} cells is described by ${D} gene readings (real studies use 20,000). We can only draw 2 or 3 dimensions. Do the cells form distinct types?`, draw(S, k) { pts.slice(0, 6).forEach((q, i) => S.alpha(S.part(k, i * 0.12, i * 0.12 + 0.3), () => { S.text(`cell ${i + 1}`, 0.04, 0.16 + i * 0.12, { size: 12, align: "left", color: p.muted }); q.v.forEach((x, j) => S.text(x.toFixed(1), 0.16 + j * 0.08, 0.16 + i * 0.12, { size: 11.5, mono: true })); })); S.alpha(S.part(k, 0.8, 1), () => S.text("… 10 gene readings each, 66 cells", 0.5, 0.92, { size: 13, color: p.muted })); } },
        { t: "Find neighbours in the original space", dur: 2600, cap: `Step 1: in the full ${D}-dimensional space, find each item's nearest neighbours. This is the only thing the map will try to preserve: who is close to whom.`, draw(S, k) { show(snaps[0], false, { focus: true }); S.alpha(S.ease(k), () => pts[focus].nn.forEach((j) => g.line(snaps[0][focus][0], snaps[0][focus][1], snaps[0][j][0], snaps[0][j][1], S.hl, 2))); side([["yellow lines: the 6 nearest", { color: S.hl }], ["neighbours in 10-D space", { color: S.hl }], ["(they look random in 2-D)", { color: p.muted }]]); } },
        { t: "Start with a random map", dur: 1800, cap: "Step 2: drop every item at a random spot on a 2D map. Right now the map means nothing.", draw(S, k) { show(snaps[0], false); } },
        { t: "Pull neighbours, push the rest", dur: 8000, cap: (k) => { const i = Math.min(snaps.length - 1, Math.floor(S.ease(k) * (snaps.length - 1))); return `Iteration ${i * 8}: every item is pulled towards its true neighbours and pushed away from everything else. Islands begin to form. The algorithm never sees any group labels, only the neighbour lists.`; }, draw(S, k) { const i = Math.min(snaps.length - 1, Math.floor(S.ease(k) * (snaps.length - 1))); show(snaps[i], false, { focus: true }); pts[focus].nn.forEach((j) => g.line(snaps[i][focus][0], snaps[i][focus][1], snaps[i][j][0], snaps[i][j][1], S.tint(S.hl, 0.6), 1.5)); side([["→ ← attract neighbours", { color: p.good }], ["← → repel everyone else", { color: p.bad }]]); } },
        { t: "Reveal the groups", dur: 2200, cap: "Now colour the cells by their true cell type (which the algorithm never saw): each island is one type. Structure in 10 dimensions is now visible in 2D.", draw(S, k) { show(snaps[snaps.length - 1], k > 0.3); } },
        { t: "How to read it (and not)", dur: 3200, cap: "Trust: points close together are similar; separate islands are different groups. Don't trust: the distance between islands or their sizes; those aren't meaningful. Results change with settings (perplexity / n_neighbors) and random seeds, so try a few. Use it to explore, not to measure.", draw(S, k) { show(snaps[snaps.length - 1], true); side([["✓ neighbours are similar", { color: p.good }], ["✓ islands = groups", { color: p.good }], ["✗ gaps between islands", { color: p.bad }], ["✗ island sizes", { color: p.bad }]]); } },
      ];
    },
  });

  /* ---------- Isolation forest ---------- */
  A.story("iforest", {
    how: "Watch isolation forest find anomalies: make random cuts through the data until a point is alone. An odd point far from the crowd is cut off in a few cuts; a normal point deep in the crowd needs many. Average over many random trees to get an anomaly score.",
    scenes(S) {
      const p = S.pal, r = A.seeded(103), pts = cloud(r, 70, 0.45, 0.48, 0.12).concat([{ x: 0.9, y: 0.88 }, { x: 0.1, y: 0.9 }, { x: 0.88, y: 0.12 }]);
      const outl = pts.length - 3, normal = pts.reduce((b, q, i) => (i < outl && Math.hypot(q.x - 0.45, q.y - 0.48) < Math.hypot(pts[b].x - 0.45, pts[b].y - 0.48) ? i : b), 0);
      // Random cuts that isolate one point: keep cutting the box it's in until it's alone
      function isolate(t, rr) { let box = [0, 1, 0, 1], ids = pts.map((q, i) => i); const cuts = []; while (ids.length > 1 && cuts.length < 30) { const f = rr() < 0.5 ? "x" : "y", lo = f === "x" ? box[0] : box[2], hi = f === "x" ? box[1] : box[3], v = lo + (hi - lo) * rr(); cuts.push({ f, v, box: box.slice() }); const left = pts[t][f] < v; ids = ids.filter((i) => (pts[i][f] < v) === left); if (f === "x") box = left ? [box[0], v, box[2], box[3]] : [v, box[1], box[2], box[3]]; else box = left ? [box[0], box[1], box[2], v] : [box[0], box[1], v, box[3]]; } return { cuts, box }; }
      const I1 = isolate(outl, A.seeded(5)), I2 = isolate(normal, A.seeded(6));
      const rr = A.seeded(7), T = 100, avg = pts.map((q, i) => { let s = 0; for (let t = 0; t < T; t++) s += isolate(i, rr).cuts.length; return s / T; });
      const mn = Math.min(...avg), mxA = Math.max(...avg), score = avg.map((a) => 1 - (a - mn) / (mxA - mn));
      const g = S.area(0.04, 0.08, 0.6, 0.94);
      const base = (colour, hl) => { g.frame(); pts.forEach((q, i) => g.dot(q.x, q.y, i === hl ? 7 : 4.5, colour ? colour(i) : p.muted, i === hl ? S.hl : p.bg)); };
      const drawCuts = (I, n) => I.cuts.slice(0, n).forEach((c, j) => { const b = c.box; if (c.f === "x") g.line(c.v, b[2], c.v, b[3], j === n - 1 ? S.hl : S.tint(p.fg, 0.55), j === n - 1 ? 2.5 : 1.5); else g.line(b[0], c.v, b[1], c.v, j === n - 1 ? S.hl : S.tint(p.fg, 0.55), j === n - 1 ? 2.5 : 1.5); });
      const side = (lines) => lines.forEach(([t, o], i) => S.text(t, 0.64, 0.2 + i * 0.08, Object.assign({ align: "left", size: 13, max: 0.34 }, o)));
      const heat = (i) => S.tint(score[i] > 0.6 ? p.bad : p.a, 0.35 + 0.65 * (score[i] > 0.6 ? score[i] : 1 - score[i]));
      return [
        { t: "Data with a few oddities", dur: 1600, cap: "A crowd of normal transactions and a few strange ones far away. No labels: nobody has marked which ones are fraud. Can we find the odd ones?", draw(S, k) { g.frame(); pts.slice(0, Math.ceil(k * pts.length)).forEach((q) => g.dot(q.x, q.y, 4.5, p.muted, p.bg)); } },
        { t: "Random cuts", dur: 2000, cap: "The idea: make a random cut (a random feature and a random value), then keep cutting the side the point is on. Count how many cuts it takes until a point is completely alone.", draw(S, k) { base(); S.alpha(S.ease(k), () => drawCuts(I1, 1)); } },
        { t: "Isolating an oddity", dur: Math.max(2400, I1.cuts.length * 800), cap: `Isolating the odd point in the corner takes only ${I1.cuts.length} cuts: it's so far from everything that random cuts separate it almost immediately.`, draw(S, k) { base(null, outl); const n = Math.max(1, Math.ceil(S.ease(k) * I1.cuts.length)); drawCuts(I1, n); side([[`cuts: ${n}`, { size: 18, color: p.bad }]]); } },
        { t: "Isolating a normal point", dur: Math.max(3000, I2.cuts.length * 450), cap: `A point in the middle of the crowd needs ${I2.cuts.length} cuts, because its neighbours keep landing on the same side. Few cuts = suspicious; many cuts = normal.`, draw(S, k) { base(null, normal); const n = Math.max(1, Math.ceil(S.ease(k) * I2.cuts.length)); drawCuts(I2, n); side([[`cuts: ${n}`, { size: 18, color: p.good }]]); } },
        { t: "Average many random trees", dur: 3000, cap: `One random tree is luck. So repeat with ${T} random trees and average the number of cuts for every point (oddity: ${avg[outl].toFixed(1)} cuts on average; centre point: ${avg[normal].toFixed(1)}). Shorter average path = higher anomaly score.`, draw(S, k) { base((i) => (k > 0.3 ? heat(i) : p.muted)); side([[`${T} random trees`, { size: 15 }], ["red = few cuts → anomaly", { color: p.bad }], ["teal = many cuts → normal", { color: p.a }]]); } },
        { t: "Flag the anomalies", dur: 2400, cap: `Rank by score and flag the top ones (the contamination setting says roughly what share to flag). The three planted oddities score highest: ${[outl, outl + 1, outl + 2].map((i) => score[i].toFixed(2)).join(", ")}. In practice, a person reviews the flagged cases.`, draw(S, k) { base(heat); pts.map((q, i) => i).sort((a, b) => score[b] - score[a]).slice(0, 3).forEach((i) => S.alpha(S.ease(k), () => S.ring(g.u(pts[i].x), g.v(pts[i].y), 13, p.bad, 3))); } },
      ];
    },
  });

  /* ---------- Autoencoder ---------- */
  A.story("ae", {
    how: "Watch an autoencoder squeeze an image through a narrow bottleneck and rebuild it. Trained only on normal line images, it rebuilds lines perfectly, but a diagonal or a blob comes out wrong. That reconstruction error is how it spots anomalies.",
    note: "This is a linear autoencoder (mathematically the same as PCA), trained in your browser on 6 line patterns. Deep autoencoders use neural networks.",
    scenes(S) {
      const p = S.pal, N = 8, Dm = 64;
      const train = []; for (const k of [1, 4, 6]) { train.push(Array.from({ length: Dm }, (_, i) => (Math.floor(i / N) === k ? 1 : 0))); train.push(Array.from({ length: Dm }, (_, i) => (i % N === k ? 1 : 0))); }
      const mean = Array.from({ length: Dm }, (_, i) => train.reduce((s, v) => s + v[i], 0) / train.length), X = train.map((v) => v.map((x, i) => x - mean[i]));
      const n = X.length, G = X.map((a) => X.map((b) => a.reduce((s, v, i) => s + v * b[i], 0))), V = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0))), M = G.map((row) => row.slice());
      for (let sw = 0; sw < 60; sw++) for (let a = 0; a < n; a++) for (let b = a + 1; b < n; b++) { if (Math.abs(M[a][b]) < 1e-10) continue; const th = (M[b][b] - M[a][a]) / (2 * M[a][b]), t = Math.sign(th || 1) / (Math.abs(th) + Math.sqrt(th * th + 1)), c = 1 / Math.sqrt(t * t + 1), s = t * c; for (let q = 0; q < n; q++) { const x = M[q][a], y = M[q][b]; M[q][a] = c * x - s * y; M[q][b] = s * x + c * y; } for (let q = 0; q < n; q++) { const x = M[a][q], y = M[b][q]; M[a][q] = c * x - s * y; M[b][q] = s * x + c * y; } for (let q = 0; q < n; q++) { const x = V[q][a], y = V[q][b]; V[q][a] = c * x - s * y; V[q][b] = s * x + c * y; } }
      const comps = Array.from({ length: n }, (_, i) => i).sort((a, b) => M[b][b] - M[a][a]).filter((i) => M[i][i] > 1e-6).map((i) => { const u = Array.from({ length: Dm }, (_, d) => X.reduce((s, row, q) => s + row[d] * V[q][i], 0)), nn = Math.hypot(...u); return u.map((v) => v / nn); });
      const K = comps.length;
      const enc = (img, k = K) => comps.slice(0, k).map((u) => u.reduce((s, v, i) => s + v * (img[i] - mean[i]), 0));
      const dec = (code) => mean.map((m, i) => m + code.reduce((s, c, j) => s + c * comps[j][i], 0));
      const err = (img, k = K) => { const rec = dec(enc(img, k)); return img.reduce((s, v, i) => s + (v - rec[i]) ** 2, 0) / Dm; };
      const LINE = Array.from({ length: Dm }, (_, i) => (i % N === 4 ? 1 : 0)), DIAG = Array.from({ length: Dm }, (_, i) => (Math.floor(i / N) === i % N ? 1 : 0)), BLOB = Array.from({ length: Dm }, (_, i) => (Math.hypot(Math.floor(i / N) - 3.5, (i % N) - 3.5) < 2.2 ? 1 : 0));
      const cell = () => Math.min(S.x(0.028), S.y(0.06)), col = (v) => S.tint(p.fg, 0.08 + 0.92 * Math.max(0, Math.min(1, v)));
      const pipeline = (img, k, o = {}) => { const c = cell(), code = enc(img, K), rec = dec(code), e = err(img);
        S.text("input", 0.12, 0.12, { size: 11, color: p.muted }); pix(S, 0.02, 0.16, N, img, c, col);
        S.alpha(S.part(k, 0.15, 0.4), () => { S.ctx.beginPath(); S.ctx.moveTo(S.x(0.27), S.y(0.16)); S.ctx.lineTo(S.x(0.42), S.y(0.36)); S.ctx.lineTo(S.x(0.42), S.y(0.5)); S.ctx.lineTo(S.x(0.27), S.y(0.7)); S.ctx.closePath(); S.ctx.fillStyle = S.tint(p.accent, 0.15); S.ctx.fill(); S.text("encoder", 0.345, 0.43, { size: 11, color: p.accent }); S.text(`${K} numbers`, 0.5, 0.3, { size: 11, color: p.muted }); code.forEach((v, j) => { S.rect(0.465, 0.34 + j * 0.035, 0.07, 0.028, S.tint(v >= 0 ? p.a : p.b, 0.25 + Math.min(0.75, Math.abs(v)))); S.text(v.toFixed(2), 0.5, 0.354 + j * 0.035, { size: 9.5 }); }); });
        S.alpha(S.part(k, 0.45, 0.7), () => { S.ctx.beginPath(); S.ctx.moveTo(S.x(0.58), S.y(0.36)); S.ctx.lineTo(S.x(0.73), S.y(0.16)); S.ctx.lineTo(S.x(0.73), S.y(0.7)); S.ctx.lineTo(S.x(0.58), S.y(0.5)); S.ctx.closePath(); S.ctx.fillStyle = S.tint(p.accent, 0.15); S.ctx.fill(); S.text("decoder", 0.655, 0.43, { size: 11, color: p.accent }); });
        S.alpha(S.part(k, 0.7, 1), () => { S.text("rebuilt", 0.86, 0.12, { size: 11, color: p.muted }); pix(S, 0.75, 0.16, N, rec, c, col); if (o.err !== false) S.text(`reconstruction error ${e.toFixed(3)} → ${e > 0.03 ? "ANOMALY" : "normal"}`, 0.5, 0.88, { size: 15, color: e > 0.03 ? p.bad : p.good }); }); };
      const errs = Array.from({ length: K }, (_, i) => ({ k: i + 1, line: err(LINE, i + 1), diag: err(DIAG, i + 1) }));
      return [
        { t: "Squeeze and rebuild", dur: 2400, cap: `An autoencoder has two halves: an encoder squeezes the input (here 64 pixels) into a few numbers (here ${K}), the bottleneck; a decoder rebuilds the 64 pixels from just those numbers. It's trained to make the copy match the original.`, draw(S, k) { pipeline(LINE, S.ease(k), { err: false }); } },
        { t: "Train on normal data only", dur: 2600, cap: "Training data: photos of normal parts only, here 6 kinds of straight-line pattern. To rebuild them through the narrow bottleneck, it must learn what lines have in common, not memorise pixels.", draw(S, k) { const c = cell() * 0.75; train.forEach((img, i) => S.alpha(S.part(k, i * 0.12, i * 0.12 + 0.3), () => pix(S, 0.04 + (i % 3) * 0.18, 0.15 + Math.floor(i / 3) * 0.4, N, img, c, col))); S.alpha(S.part(k, 0.75, 1), () => S.text("✓ training examples", 0.8, 0.5, { size: 14, color: p.good })); } },
        { t: "A normal input", dur: 3200, cap: `A line comes in. The encoder turns it into ${K} numbers, the decoder rebuilds it: a near-perfect copy. Reconstruction error ${err(LINE).toFixed(3)}: normal.`, draw(S, k) { pipeline(LINE, k); } },
        { t: "An unusual input: diagonal", dur: 3200, cap: `A part with a diagonal scratch comes in. The autoencoder has only learned rows and columns, so the best it can do is a blurry mix of them. Error ${err(DIAG).toFixed(3)}: much higher, flagged as an anomaly.`, draw(S, k) { pipeline(DIAG, k); } },
        { t: "An unusual input: blob", dur: 2800, cap: `A part with a blob-shaped defect: nothing like the training data. Error ${err(BLOB).toFixed(3)}. Set a threshold from the errors on normal data, and anything above it is flagged: fraud, faulty machines, odd network traffic.`, draw(S, k) { pipeline(BLOB, k); } },
        { t: "Bottleneck size", dur: 3000, cap: "The bottleneck is a trade-off. Too narrow (1–2 numbers) and even normal lines rebuild badly. Wide enough and normal data rebuilds perfectly while unusual data still doesn't. Too wide and it just copies everything, so nothing looks unusual.", draw(S, k) { const g = S.area(0.12, 0.15, 0.9, 0.82), mx = Math.max(...errs.map((e) => Math.max(e.line, e.diag))); g.frame("bottleneck size →", "error"); errs.forEach((e, i) => S.alpha(S.part(k, i / K, i / K + 0.3), () => { const x = (i + 0.5) / K; S.rect(g.u(x) - 0.035, g.v(e.line / mx), 0.03, g.v(0) - g.v(e.line / mx), p.a); S.rect(g.u(x) + 0.005, g.v(e.diag / mx), 0.03, g.v(0) - g.v(e.diag / mx), p.b); g.text(e.k, x, -0.06, { size: 11 }); })); S.text("■ line (normal)", 0.7, 0.9, { size: 12, color: p.a }); S.text("■ diagonal (unusual)", 0.4, 0.9, { size: 12, color: p.b }); } },
        { t: "What autoencoders are used for", dur: 2600, cap: "Uses: anomaly detection (as here), compression, denoising (train it to rebuild clean images from noisy ones), and learning compact features. A variational autoencoder (VAE) makes the bottleneck smooth, so you can sample it to generate new images.", draw(S, k) { [["anomaly detection", "high error = unusual"], ["compression", "64 → 5 numbers"], ["denoising", "noisy in, clean out"], ["generation (VAE)", "sample the bottleneck"]].forEach(([a, b], i) => S.alpha(S.part(k, i * 0.2, i * 0.2 + 0.3), () => S.box(0.27 + (i % 2) * 0.46, 0.32 + Math.floor(i / 2) * 0.34, 0.38, 0.22, a, { sub: b, stroke: i ? p.line : S.hl, size: 14 }))); } },
      ];
    },
  });
})();
